using System;
using System.IO;
using System.Collections.Generic;
using ScoreModern.RecoveredFragments;
class StringOutputRuntimeProof {
 class Record {public string Name;public CharacterRoutineWords Words;public ushort CS,IP;}
 static ushort H(string s){return Convert.ToUInt16(s,16);}
 static Record Parse(string line){string[] a=line.Split(' ');return new Record{Name=a[0],Words=new CharacterRoutineWords{AX=H(a[1]),BX=H(a[2]),CX=H(a[3]),DX=H(a[4]),SI=H(a[5]),DI=H(a[6]),BP=H(a[7]),DS=H(a[8]),ES=H(a[9]),SS=H(a[10]),SP=H(a[11])},CS=H(a[12]),IP=H(a[13])};}
 static string Show(CharacterRoutineWords w){return w.AX+":"+w.BX+":"+w.CX+":"+w.DX+":"+w.SI+":"+w.DI+":"+w.BP+":"+w.DS+":"+w.ES+":"+w.SS+":"+w.SP;}
 class Replay:IStringOutputContext {
  public string Folder;public byte[] Memory;public ushort Segment,CodeSegment;public List<Record> Events;public int Calls,Compared;
  public byte ReadByte(ushort s,ushort o){if(s!=Segment)throw new Exception("Segment");return Memory[o];}
  public ushort ReadWord(ushort s,ushort o){if(s!=Segment)throw new Exception("Segment");return (ushort)(Memory[o]|Memory[(ushort)(o+1)]<<8);}
  public void WriteWord(ushort s,ushort o,ushort v){if(s!=Segment)throw new Exception("Segment");Memory[o]=(byte)v;Memory[(ushort)(o+1)]=(byte)(v>>8);}
  public byte[] Load(string name){byte[] b=File.ReadAllBytes(Path.Combine(Folder,name+"-ss.bin"));if(b.Length!=65536)throw new Exception("Capture length");return b;}
  public void Compare(byte[] expected){for(int i=0;i<65536;i++)if(Memory[i]!=expected[i])throw new Exception("Stack/data memory "+i.ToString("X4"));Compared+=65536;}
  public CharacterRoutineResult CallCharacter(CharacterRoutineWords w,ushort targetSegment,ushort targetOffset){Record request=Events[Calls*2],result=Events[Calls*2+1];if(request.CS!=targetSegment||request.IP!=targetOffset||Show(w)!=Show(request.Words))throw new Exception("Character call words "+Calls);Compare(Load(request.Name));if(ReadWord(w.SS,w.SP)!=0x70b||ReadWord(w.SS,(ushort)(w.SP+2))!=CodeSegment)throw new Exception("Far call frame");Memory=Load(result.Name);Calls++;return new CharacterRoutineResult{Words=result.Words,CS=result.CS,IP=result.IP};}
 }
 static int Main(string[] args){try{byte[] raw=File.ReadAllBytes(args[0]),mz=File.ReadAllBytes(args[1]);ushort load=H(args[2]);string p=args[3];int start=0x16fa0+0x6f6;byte[] expected=new byte[29];Array.Copy(raw,start,expected,0,29);int count=BitConverter.ToUInt16(mz,6),table=BitConverter.ToUInt16(mz,0x18),patched=0;for(int i=0;i<count;i++){int off=BitConverter.ToUInt16(mz,table+4*i),seg=BitConverter.ToUInt16(mz,table+4*i+2),site=seg*16+off;if(site>=start&&site<start+29){int at=site-start;ushort v=(ushort)(BitConverter.ToUInt16(expected,at)+load);expected[at]=(byte)v;expected[at+1]=(byte)(v>>8);patched++;}}if(patched!=1)throw new Exception("Relocation extent");byte[] live=File.ReadAllBytes(Path.Combine(p,"routine-code.bin"));if(live.Length!=29)throw new Exception("Code length");for(int i=0;i<29;i++)if(live[i]!=expected[i])throw new Exception("Relocated code");string[] lines=File.ReadAllLines(Path.Combine(p,"string-replay-words.txt"));Record entry=Parse(lines[0]);List<Record> events=new List<Record>();for(int i=1;i<lines.Length;i++)events.Add(Parse(lines[i]));if(events.Count%2!=1)throw new Exception("Event count");Replay replay=new Replay{Folder=p,Segment=entry.Words.SS,CodeSegment=entry.CS,Memory=File.ReadAllBytes(Path.Combine(p,"entry-ss.bin")),Events=events};StringOutputResult r=StringOutputRoutine.Run(replay,entry.Words,entry.CS,BitConverter.ToUInt16(live,19));Record end=events[events.Count-1];if(!r.ReachedStringReturn||replay.Calls!=(events.Count-1)/2||Show(r.Result.Words)!=Show(end.Words)||r.Result.CS!=end.CS||r.Result.IP!=end.IP)throw new Exception("String return");replay.Compare(replay.Load(end.Name));Console.WriteLine("PASS original string-loop replay: 29 relocated code bytes, "+replay.Calls+" character-call entry/return states, far return/results and "+replay.Compared+" stack/data byte comparisons. Character-callee effects are measured replay inputs; the native loop itself supplies its far-call frames. No text encoding, BIOS or rendering equivalence claimed.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
